 92	    private Node insert(Node current, int data, InsertionState state) {
 93	        boolean redRedConflict = false;
 94	
 95	        if (current == null) {
 96	            return new Node(data, Color.RED);
 97	        }
 98	
 99	        if (data < current.data) {
100	            current.left = insert(current.left, data, state);
101	            current.left.parent = current;
102	            redRedConflict = current != root && isRed(current) && isRed(current.left);
103	        } else {
104	            current.right = insert(current.right, data, state);
105	            current.right.parent = current;
106	            redRedConflict = current != root && isRed(current) && isRed(current.right);
107	        }
108	
109	        current = applyPendingRotation(current, state);
110	
111	        if (redRedConflict) {
112	            resolveRedRedConflict(current, state);
113	        }
114	
115	        return current;
116	    }
