118	    private Node applyPendingRotation(Node current, InsertionState state) {
119	        if (state.rotateLeftLeft) {
120	            current = rotateLeft(current);
121	            recolorAfterSingleRotation(current, current.left);
122	            state.rotateLeftLeft = false;
123	        } else if (state.rotateRightRight) {
124	            current = rotateRight(current);
125	            recolorAfterSingleRotation(current, current.right);
126	            state.rotateRightRight = false;
127	        } else if (state.rotateRightLeft) {
128	            current.right = rotateRight(current.right);
129	            current.right.parent = current;
130	            current = rotateLeft(current);
131	            recolorAfterSingleRotation(current, current.left);
132	            state.rotateRightLeft = false;
133	        } else if (state.rotateLeftRight) {
134	            current.left = rotateLeft(current.left);
135	            current.left.parent = current;
136	            current = rotateRight(current);
137	            recolorAfterSingleRotation(current, current.right);
138	            state.rotateLeftRight = false;
139	        }
140	
141	        return current;
142	    }
