144	    private void resolveRedRedConflict(Node current, InsertionState state) {
145	        Node parent = current.parent;
146	        if (parent.right == current) {
147	            if (isBlack(parent.left)) {
148	                if (isRed(current.left)) {
149	                    state.rotateRightLeft = true;
150	                } else if (isRed(current.right)) {
151	                    state.rotateLeftLeft = true;
152	                }
153	            } else {
154	                recolorForRedUncle(current, parent.left);
155	            }
156	        } else {
157	            if (isBlack(parent.right)) {
158	                if (isRed(current.left)) {
159	                    state.rotateRightRight = true;
160	                } else if (isRed(current.right)) {
161	                    state.rotateLeftRight = true;
162	                }
163	            } else {
164	                recolorForRedUncle(current, parent.right);
165	            }
166	        }
167	    }
